entries[455849] = { ["name"] = "Mal der Paranoia", ["text"] = "Sofort\nVon Takazj markierte Spielercharaktere werden von Paranoia erfüllt, was Spielercharaktere ohne ' Mal der Paranoia ' innerhalb von 0 Metern tötet.\n\nMit dem Mal belegte Spielercharaktere erschaffen ein ' Partikel der überreizten Paranoia ', wenn sie von bestimmten Fähigkeiten des Seidenhofs getroffen werden." }
