entries[455854] = { ["name"] = "Instabile Formation", ["text"] = "Sofort\nDie große, instabile Form dieser Kreatur verleiht ihr Kraft. Angriffe können diese Form langsam verkleinern, lösen aber einen 'Dunkelheitausbruch' aus. Diese Form zu verbrauchen, macht die Kreatur für eine kurze Dauer verwundbar, bevor sie sich in einer Explosion neu formt und allen Spielercharaktere in der Nähe Schattenschaden zufügt.\n(Procchance: 75%, 1s Abklingzeit)" }
