entries[455863] = { ["name"] = "Mal des Todes", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpielercharaktere werden vom Hof verurteilt und mit der Essenz des Todes erfüllt, die alle 1 Sek. 17268945 Chaosschaden verursacht. Diese Aura bleibt über den Tod hinaus erhalten." }
