entries[455953] = { ["name"] = "Reaktiver Schaum", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ein Spielercharakter den Schaum berührt, explodiert er und belegt den Spielercharakter mit ' Konzentriertes Toxin '.\n\nDiese Explosion schleudert den Spielercharakter 8 Meter in die Luft und fügt allen Spielercharakteren 1151263 Naturschaden zu und belegt sie mit ' Schäumendes Toxin ' und ' Toxische Reaktion '. Außerdem wird ein Giftklumpen weggeschleudert, der ' Giftige Wellen ' auslöst.\n\n' Toxinnova ' zerstreut explodierten Schaum zu einer Lache aus ' Säure '." }
