entries[455960] = { ["name"] = "Alles-im-Eintopf", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nStellt einen Topf mit Alles-im-Eintopf auf, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 2250000 / 5 * 20) Gesundheit und ( 750000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer niedrigster Sekundärwert wird 1 Stunde lang um 470 erhöht." }
