entries[456157] = { ["name"] = "Blutiger Köder", ["text"] = "12 - 15 Meter Reichweite\nSofort\nWerft diesen Fisch ins Wasser zurück, um einen Stapel von 'Blutiger Köder' zu erhalten, der 5 Min. lang blutrote Dornhaie an Eure Position lockt.\n\nDieser Effekt erhöht Eure Chancen um 10% und ist bis zu 10-mal stapelbar. Bewegung zerstreut Euren Geruch und unterbricht den Effekt." }
