entries[456479] = { ["name"] = "Schicksalsgebundene Münze (Kopf)", ["text"] = "Sofort\nWirft immer, wenn ein Finishing-Move 5 oder mehr Combopunkte verbraucht, eine schicksalsgebundene Münze. Kopf erhöht den Schaden Eurer Angriffe 15 Sek. lang, oder bis Ihr Zahl werft, um 10%. Zahl fügt Eurem Ziel (210% der Angriffskraft) kosmischen Schaden zu.\n\nImmer wenn der Wurf das gleiche Ergebnis wie der vorherige Wurf hat, wird bei Kopf der Schaden um zusätzliche 2% und bei Zahl der Schaden um 10% erhöht." }
