entries[456535] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nPfeilspitzengötze aus Porzellan\nBranns Zauber und Fähigkeiten haben eine Chance, Gegner zu schwächen, was die Chance auf kritische Treffer gegen diese Gegner 5 Sek. lang um 20 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
