entries[456550] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der brutalen Kraft\nSpringt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456551] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der Erdenmutter\nBranns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 15 % seiner fehlenden Gesundheit gewährt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456552] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nUnverwüstlicher Eisengötze\nWenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 4 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456553] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLichtberührter Götze\nSobald ein Spielercharakter eine Defensivfähigkeit mit einer Abklingzeit von 30 Sek. oder länger benutzt, wird der Götze aktiviert und heilt ihn 1 lang alle 10 Sek. Sek. um ( 100 / 100)% seiner maximalen Gesundheit.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456554] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 10 %. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 5 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456555] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze des finalen Willens\nIm Kampf bestimmt Brann einen Spielercharakter, der seinen Schuss 4 Sek. lang lenkt, bevor er ihn auf die Position abfeuert und dem ersten getroffenen Gegner moderaten körperlichen Schaden zufügt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456556] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAmorphes Relikt\nBeim Kampfbeginn erhalten Spielercharaktere entweder ' Massiv ' oder ' Miniatur ' bis zum Ende des Kampfes.\n\n' Massiv '\nErhöht Eure Größe um 20 %, Eure maximale Gesundheit um 5 % und Euren verursachten Schaden und hervorgerufene Heilung um 3 %.\n\n' Miniatur '\nVerringert Eure Größe um 20 % und erhöht Eure Bewegungsgeschwindigkeit um 5 % und Euer Tempo um 3 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456557] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nZeitverlorenes Relikt\nBranns Zauber und Fähigkeiten haben eine Chance, Energieausbrüche zu erzeugen und so den Zeitstrom für alle Einheiten in der Nähe 12 Sek. lang um 15 % zu verzerren.\n\nDie Zeitverzerrung hat einen Einfluss auf Zauber-, Bewegungs- und regelmäßige Effekte, Abklingzeiten und Angriffstempo.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456558] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Sucher aus alten Zeiten\nWenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 20 %, ein mächtiges Artefakt freizulegen, das Eurer Gruppe einen mächtigen Segen gewährt.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456559] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLebloses Relikt der Nekrotischen Fäulnis\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 14 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 6 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456560] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Empfindungsfähigkeit\nWenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456561] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nReliktblut von Zekvir\nAn zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\nBlutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 1% und maximale Gesundheit um 5% verringert. Hält 1 Min. lang an.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
