entries[456575] = { ["name"] = "Energie-im-Knie", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 937500 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\nEnergie-im-Knie\nWenn Ihr mindestens 10 Sek. mit Trinken verbringt, erhaltet Ihr 10 Min. lang 167 Geschwindigkeit sowie die Fähigkeit, auf dem Wasser zu laufen." }
entries[456576] = { ["name"] = "Proteinschlabber", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr Satt , Euer niedrigster Sekundärwert wird um [Quellwert] erhöht und Ihr werdet um 1% größer. Hält 15 Min. lang an.", ["unresolvedValues"] = true }
