entries[456586] = { ["name"] = "Algarische Wahrnehmung", ["text"] = "12 - 15 Meter Reichweite\nSofort\nWirft den Fisch zurück ins Wasser, um 30 Sek. lang 45 Wahrnehmung zu erhalten.\n\nDurch das Zurückwerfen mehrerer Fische kann diese Stärkung auf bis zu 5 Min. verlängert werden." }
entries[456587] = { ["name"] = "Königsköder", ["text"] = "12 - 15 Meter Reichweite\nSofort\nWirft diesen Fisch zurück ins Wasser und gewährt einen Stapel von 'Königsköder', der die Gewässer um Euch herum vor verderbten Geisterfischen schützt und 30 Sek. lang die Wahrscheinlichkeit erhöht, einen Königinnenköderfisch zu fangen.\n\nDurch das Zurückwerfen mehrerer Fische kann diese Stärkung auf bis zu 10 Min. verlängert werden." }
entries[456588] = { ["name"] = "Insel von Dorn", ["text"] = "Sofort\nEmpfohlene Fertigkeit: 1\n\nRuhige Gewässer und vertraute Bedingungen machen dieses Gebiet perfekt für Angler, die ihre Fähigkeiten ausbauen wollen, bevor sie tiefer nach Khaz Algar vorstoßen.\n\nAngelmöglichkeiten in dieser Zone:\n- Glimmerbecken\n- Uferschatz\n- Sternguckerschwarm\n- Schwärender Fäulnisteich\n- Ruhige Oberflächenwellen\n- Flussbarschteich\n- Blutbarschschwarm\nBeruf:\nAngeln (1)" }
entries[456589] = { ["name"] = "Die Schallenden Tiefen", ["text"] = "Sofort\nEmpfohlene Fertigkeit: 125\n\nEin Höhlensystem, gekennzeichnet von der Verbindung zwischen Industrie und Anpassung. In den Flüssen wimmelt es von allerlei Leben von oben und unten.\n\nAngelmöglichkeiten in dieser Zone:\n- Glimmerbecken\n- Ruhige Oberflächenwellen\n- Flussbarschteich\n- Anglersucherstrom\n- Treibender tiefer Schatz\nBeruf:\nAngeln (75)" }
entries[456590] = { ["name"] = "Heilsturz", ["text"] = "Sofort\nEmpfohlene Fertigkeit: 225\n\nEin Gebiet, das erstaunlicherweise alle Arten von Leben ermöglicht. Tiefe Abgründe und kilometerweite unterirdische Flüsse bilden eine Kreuzung, an der Angler ihre Fähigkeiten auf die Probe stellen können.\n\nAngelmöglichkeiten in dieser Zone:\n- Ruhige Oberflächenwellen\n- Glimmerbecken\n- Anglersucherstrom\n- Treibender tiefer Schatz\n- Energieerfüllter Sekretfleck\n- Geflüster der Tiefe\n- Königliche Welle\n- Blut im Wasser\nBeruf:\nAngeln (150)" }
entries[456591] = { ["name"] = "Azj-Kahet", ["text"] = "Sofort\nEmpfohlene Fertigkeit: 375\n\nKarge Gewässer, die mit dem Sekret diverser Seltsamkeiten geronnen sind. Sehr schwer zu durchqueren für ungenügend vorbereitete Angler.\n\nIn dieser Zone:\n- Ruhige Oberflächenwellen\n- Glimmerbecken\n- Energieerfüllter Sekretfleck\n- Königliche Welle\n- Slumhaischwarm\n- Geflüster der Tiefe\nBeruf:\nAngeln (225)" }
entries[456592] = { ["name"] = "Hüllenfischschatz", ["text"] = "Sofort\nBringt die Inhalte des Hüllenfischmagens hervor." }
entries[456593] = { ["name"] = "Nicht so schnell!" }
entries[456594] = { ["name"] = "Verlangsamt" }
entries[456595] = { ["name"] = "Geflüster der Tiefe", ["text"] = "Sofort\nDer Fisch tritt in dichten Schwärmen auf und hat seinen Namen durch seine tintenschwarzen Schuppen erhalten, die aneinander reiben und vibrieren. Diese Vibrationen schrecken Räuber ab und sind so laut, dass man sie selbst über Wasser hören kann.\n\nBesondere Verwendung:\n\nGeflüster der Tiefe\n\nSetzt den flüsternden Sterngucker ein, um schlummernde Quastenflosser aus den Tiefen Azj-Kahets hervorzulocken.\n\nVerbreitungsgebiete:\n\n- Insel von Dorn\n- Schallende Tiefen\n- Heilsturz\n- Sireneninsel\n- K'aresh-Oase\n\nFischschwärme:\n\n- Sternguckerschwarm" }
