entries[456617] = { ["name"] = "Geladene Spule", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde lädt das Ziel für 8 Sek. mit elektrischer Energie auf, fügt ihm alle 1 Sek. Naturschaden zu und verringert seine Bewegungsgeschwindigkeit für 5 Sek. um 50%." }
