entries[456636] = { ["name"] = "Königliches Netz", ["text"] = "60 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde entfesselt Schuss konzentrierter königlicher Seide auf einen Spielercharakter, fügt allen Spielercharakteren in einem Bereich von 6 Metern 25 Naturschaden zu und hinterlässt dabei ein Netz, das Spielercharaktere alle 2 Sek. um 50% verlangsamt und ihnen 8 Naturschaden zufügt." }
entries[456638] = { ["name"] = "Königliches Netz", ["text"] = "60 Meter Reichweite\nSofort\nDer Zaubernde entfesselt Schuss konzentrierter königlicher Seide auf einen Spielercharakter, fügt allen Spielercharakteren in einem Bereich von 6 Metern 25 Naturschaden zu und hinterlässt dabei ein Netz, das Spielercharaktere alle 2 Sek. um 50% verlangsamt und ihnen 8 Naturschaden zufügt." }
