entries[456652] = { ["name"] = "Geladene Sturmwoge", ["text"] = "Sofort\nEure Zauber haben eine Chance, eine aufgeladene Sturmkrähe herbeizurufen, die ( 1 * 1192 ) Naturschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden, und das Tempo um 87 erhöht. Das Tempo wird mit jedem getroffenen Gegner weiter erhöht." }
