entries[456698] = { ["name"] = "Unheiliger Befehlshaber", ["text"] = "Sofort\nWenn Ihr einen Diener beschwört, wird Euer Tempo 8 Sek. lang um 1% erhöht, bis maximal 4%." }
entries[456699] = { ["name"] = "Lebloses Relikt der Nekrotischen Fäulnis", ["text"] = "Sofort\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100% ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 14% ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 6% erhöht." }
entries[456700] = { ["name"] = "Steigender Zorn", ["text"] = "Sofort\nDer Einsatz einer Fähigkeit, die Heilige Kraft verbraucht, erhöht den verursachten Schaden und die verursachte Heilung bei Eurem nächsten Einsatz von 'Zornige Vergeltung' um 0.5%. Dieser Effekt ist stapelbar." }
