entries[456706] = { ["name"] = "Weberschnur der Algari", ["text"] = "Wirken in 2 sek.\nReagenzien:\nHändchen fürs Kunsthandwerk (100), Mooswollenfaden (50), Weberfadenspule (500)\nOptionale Reagenzien:\nStickereifaden (#333)\nBerufsausbilder:\nSchneiderei von Khaz Algar (50)\nKosten:\n270\n\nWeberschnur der Algari\nWird an Kriegsmeute gebunden\nBenutzen: Spinnt den Faden in Eure Angelschnur und gewährt die folgende Aura:\n\nWeberschnur der Algari\n\nSucherfäden und Anglerfäden, die Ihr in ganz Khaz Algar findet, erhöhen die durch Eure Angelrute gewährte Wahrnehmung und Fertigkeit permanent, bis maximal 100.\n45\nBenötigt Angeln von Khaz Algar\n(1)\n\"Eine geduldige und elastische Angelschnur.\"" }
entries[456707] = { ["name"] = "Hysterie", ["text"] = "60 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde verflucht alle Spielercharaktere innerhalb von 40 Metern und fügt ihnen so alle 2 Sek. 1 Schattenschaden zu. Dieser Effekt wird alle 2 Sek. gestapelt." }
entries[456708] = { ["name"] = "Relikt der Empfindungsfähigkeit", ["text"] = "Sofort\nWenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt." }
entries[456711] = { ["name"] = "Schattenlavaschlag", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek.\nInflicts 7273348 Shadowflame damage to enemies within 40 yards of the impact." }
