entries[456934] = { ["name"] = "Makroraketenmassaker", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\nSehr wirksam bei unbeweglichen Zielen." }
entries[456935] = { ["name"] = "Makroraketenmassaker", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\nSehr wirksam bei unbeweglichen Zielen." }
entries[456936] = { ["name"] = "Sengendes Licht", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nDer Zaubernde bestrahlt das Ziel mit Licht, verursacht Heiligschaden und verbrennt das Ziel 8 Sek. lang alle 2 Sek. für zusätzlichen Heiligschaden." }
entries[456938] = { ["name"] = "Schattenblick", ["text"] = "50 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde feuert einen Strahl Schattenenergie auf sein Ziel, der auf bis zu 2 weitere Spielercharaktere überspringt und dem ersten Ziel 13 Schattenschaden zufügt. Fügt jedem folgenden Ziel weniger Schaden zu." }
entries[456939] = { ["name"] = "Brennende Verkümmerung", ["text"] = "Erhöht den Schaden von 'Schattenbrand' um 20%. Die kritische Trefferchance von 'Schattenbrand' ist um weitere 50% erhöht, wenn ein Ziel mit 30% oder weniger Gesundheit getroffen wird." }
entries[456940] = { ["name"] = "Heilige Woge", ["text"] = "30 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde entfesselt eine Welle der Zerstörung, fügt allen getroffenen Spielercharakteren Heiligschaden zu und desorientiert sie 2 Sek. lang." }
entries[456942] = { ["name"] = "Bebendes Schmettern", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde schlägt auf den Boden und bringt ihn zum Beben, fügt allen Spielercharakteren körperlichen Schaden zu und verringert deren Bewegungsgeschwindigkeit 10 Sek. lang um 30%." }
entries[456943] = { ["name"] = "Abscheuliche Grausamkeit", ["text"] = "Wenn 'Schattenbrand' ein Ziel mit 30% oder weniger Gesundheit nicht tötet, wird seine Abklingzeit um 5 Sek. verringert." }
