entries[456946] = { ["name"] = "Dämonenfeuermeisterschaft", ["text"] = "Erhöht den Schaden von 'Dämonenfeuer kanalisieren' um 30% und lässt es seinen Schaden 35% schneller zufügen." }
entries[456948] = { ["name"] = "Läuterungsprotokoll", ["text"] = "Kanalisiert (Wirken in 8 sek.)\nDer Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen." }
entries[456951] = { ["name"] = "Verbesserter Chaosblitz", ["text"] = "Erhöht den Schaden von 'Chaosblitz' um 10% und verringert dessen Zauberzeit um 0.5 Sek." }
entries[456952] = { ["name"] = "Läuterungsprotokoll", ["text"] = "300 Meter Reichweite\nSofort\nDer Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen." }
entries[456954] = { ["name"] = "Geschenk des Sonnenkönigs", ["text"] = "Sofort\nHeilt das Ziel alle 1 Sek. um 1% seiner maximalen Gesundheit." }
entries[456956] = { ["name"] = "Läuterungsprotokoll", ["text"] = "300 Meter Reichweite\nSofort\nDer Zaubernde ruft eine Salve geschmolzener Meteore hinab, die Spielercharakteren innerhalb von 8 Metern jeweils 6 Feuerschaden zufügen." }
entries[456957] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nPfeilspitzengötze aus Porzellan\nBranns Zauber und Fähigkeiten haben eine Chance, Gegner zu schwächen, was die Chance auf kritische Treffer gegen diese Gegner 5 Sek. lang um 30 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456958] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der brutalen Kraft\nSpringt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird. Dieser Effekt hat eine Chance, bis zu 2 -mal hintereinander aufzutreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456959] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der Erdenmutter\nBranns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 30 % seiner fehlenden Gesundheit gewährt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456960] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nUnverwüstlicher Eisengötze\nWenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 6 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456961] = { ["name"] = "Zünftig satt werden", ["text"] = "Sofort\nErhöht Werte und gewährt zusätzliche Effekte basierend auf den Nahrungsmitteln aus Khaz Algar, die verspeist wurden." }
entries[456962] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLichtberührter Götze\nSobald ein Spielercharakter eine Defensivfähigkeit mit einer Abklingzeit von 30 Sek. oder länger benutzt, wird der Götze aktiviert und heilt ihn 10 Sek. lang alle 1 Sek. um ( 200 / 100)% seiner maximalen Gesundheit.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456963] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze des finalen Willens\nIm Kampf bestimmt Brann einen Spielercharakter, der seinen Schuss 4 Sek. lang lenkt, bevor er ihn auf die Position abfeuert und dem ersten getroffenen Gegner erheblichen körperlichen Schaden zufügt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456965] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAmorphes Relikt\nBeim Kampfbeginn erhalten Spielercharaktere entweder Massiv oder Miniatur bis zum Ende des Kampfes.\n\nMassiv\nErhöht Eure Größe um 20%, Eure maximale Gesundheit um 10% und Euren verursachten Schaden und hervorgerufene Heilung um 6%.\n\nMiniatur\nVerringert Eure Größe um 20% und erhöht Eure Bewegungsgeschwindigkeit um 10% und Euer Tempo um 6%.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456966] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nZeitverlorenes Relikt\nBranns Zauber und Fähigkeiten haben eine Chance, Energieausbrüche zu erzeugen und so den Zeitstrom für alle Einheiten in der Nähe 12 Sek. lang um 20 % zu verzerren.\n\nDie Zeitverzerrung hat einen Einfluss auf Zauber-, Bewegungs- und regelmäßige Effekte, Abklingzeiten und Angriffstempo.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456967] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Sucher aus alten Zeiten\nWenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 35 %, ein mächtiges Artefakt freizulegen, das Eurer Gruppe einen mächtigen Segen gewährt.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456968] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit und ( 675000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang ( 470 * .7) kritischen Trefferwert." }
entries[456969] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLebloses Relikt der Nekrotischen Fäulnis\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 11 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 8 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456970] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Empfindungsfähigkeit\nWenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456971] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nReliktblut von Zekvir\nAn zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\nBlutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 2% und maximale Gesundheit um 5% verringert. Hält 1 Min. lang an.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456972] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 20 %. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 10 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456973] = { ["name"] = "Stachelausbruch", ["text"] = "50 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde taucht ab, bevor er hervorbricht und Stacheln mit sich zieht, die Spielercharakteren, die von ihnen getroffen werden, 25 körperlichen Schaden zufügen." }
entries[456975] = { ["name"] = "Avatar der Zerstörung", ["text"] = "Beim Verbrauchen von 'Ritual des Ruins' wird ein Oberdämon für 8 Sek. beschworen.\n\nOberdämon beschwören\nGeneriert 1 Seelensplitterfragment alle 1 Sek. und wirkt 'Chaosblitz' zu 80% Effektivität auf das Ziel des Zaubernden." }
