entries[456994] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 30 %. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 15 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
