entries[456996] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der brutalen Kraft\nSpringt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen massiven körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird. Dieser Effekt hat eine Chance, bis zu 3 -mal hintereinander aufzutreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456997] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze der Erdenmutter\nBranns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 70 % seiner fehlenden Gesundheit gewährt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456998] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nUnverwüstlicher Eisengötze\nWenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 10 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[456999] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLichtberührter Götze\nSobald ein Spielercharakter eine Defensivfähigkeit mit einer Abklingzeit von 30 Sek. oder länger benutzt, wird der Götze aktiviert und heilt ihn 10 Sek. lang alle 1 Sek. um ( 400 / 100)% seiner maximalen Gesundheit.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457001] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGötze des finalen Willens\nIm Kampf bestimmt Brann einen Spielercharakter, der seinen Schuss 4 Sek. lang lenkt, bevor er ihn auf die Position abfeuert und den ersten beiden getroffenen Gegnern massiven körperlichen Schaden zufügt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457002] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAmorphes Relikt\nBeim Kampfbeginn erhalten Spielercharaktere entweder Massiv oder Miniatur bis zum Ende des Kampfes.\n\nMassiv\nErhöht Eure Größe um 20 %, Eure maximale Gesundheit um 20 % und Euren verursachten Schaden und hervorgerufene Heilung um 12 %.\n\nMiniatur\nVerringert Eure Größe um 20 % und erhöht Eure Bewegungsgeschwindigkeit um 20 % und Euer Tempo um 12 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457003] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nZeitverlorenes Relikt\nBranns Zauber und Fähigkeiten haben eine Chance, Energieausbrüche zu erzeugen und so den Zeitstrom für alle Einheiten in der Nähe 12 Sek. lang um 30 % zu verzerren.\n\nDie Zeitverzerrung hat einen Einfluss auf Zauber-, Bewegungs- und regelmäßige Effekte, Abklingzeiten und Angriffstempo.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457004] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Sucher aus alten Zeiten\nWenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 50 %, bis zu 2 mächtige Artefakte freizulegen, die Eurer Gruppe einen mächtigen Segen gewähren.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457005] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLebloses Relikt der Nekrotischen Fäulnis\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 3 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 12 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457006] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRelikt der Empfindungsfähigkeit\nWenn eine Stahlfalle aktiviert wird, besteht eine Chance, dass Brann eine zusätzliche Falle auslegt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457007] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nReliktblut von Zekvir\nAn zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\nBlutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 2% und maximale Gesundheit um 3% verringert. Hält 1 Min. lang an.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457008] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nOptimiertes Relikt\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 40 %. Bei Kampfeintritt wird das Tempo der Gruppenmitglieder für 8 Sek. um 20 % erhöht.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[457013] = { ["name"] = "Chiharmonie", ["text"] = "100 Meter Reichweite\nSofort\n'Erneuernder Nebel' erhöht die durch Euch erhaltene Heilung des Ziels für die ersten 8 Sek. seiner Dauer um 25%, kann während dieser Zeit aber nicht auf ein neues Ziel überspringen." }
entries[457017] = { ["name"] = "Flensmesser", ["text"] = "'Zerhäckseln' sorgt dafür, dass [ Meucheln : 'Verstümmeln' /\n\nGesetzlosigkeit, Täuschung\n'Meucheln' ] zusätzlich (40% der Angriffskraft) Seuchenschaden verursacht." }
entries[457018] = { ["name"] = "Entmutigt", ["text"] = "150 Meter Reichweite\nSofort\nDiese Kreatur ist verstört. Vermutlich, weil sie von einem Schatten verehrenden, Lila tragenden Kultisten beobachtet wird, den Ihr nicht sehen könnt..." }
