entries[457049] = { ["name"] = "Satt", ["text"] = "Sofort\nSatt\n\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang 470 kritischen Trefferwert." }
entries[457052] = { ["name"] = "Mal des Todespirschers", ["text"] = "Meucheln\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Hinterhalt' aus der Verstohlenheit einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von 'Hinterhalt' oder 'Verstümmeln' um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein.\n\nTäuschung\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Schattenschlag' aus der Verstohlenheit oder 'Schattentanz' einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein." }
entries[457053] = { ["name"] = "Beseitigt die Zeugen", ["text"] = "Meucheln\nNachdem Ihr ein Ziel mit 'Mal des Todespirschers' belegt, verursacht Euer nächster Einsatz von 'Dolchfächer' zusätzlich (100% der Angriffskraft) Seuchenschaden und erzeugt 1 zusätzlichen Combopunkt.\n\nTäuschung\nNachdem Ihr ein Ziel mit 'Mal des Todespirschers' belegt, verursacht Euer nächster Einsatz von 'Shurikensturm' zusätzlich (100% der Angriffskraft) Seuchenschaden und erzeugt 1 zusätzlichen Combopunkt." }
entries[457054] = { ["name"] = "Zur Strecke bringen", ["text"] = "Automatische Angriffe gegen markierte Ziele verursachen zusätzlich (25% der Angriffskraft) Seuchenschaden." }
entries[457055] = { ["name"] = "Einzelner Fokus", ["text"] = "Schaden, der anderen Zielen als dem von Euch markierten Ziel zugefügt wird, fügt dem von Euch markierten Ziel 5% Seuchenschaden zu." }
entries[457056] = { ["name"] = "Lauernde Dunkelheit", ["text"] = "Meucheln\nErhöht 30 Sek. lang den von Euch verursachten Naturschaden um 30%, nachdem 'Todesmal' ausläuft.\n\nTäuschung\nErhöht 30 Sek. lang den von Euch verursachten Schattenschaden um 30%, nachdem 'Schattenklingen' ausläuft." }
entries[457057] = { ["name"] = "Schattenwandler", ["text"] = "Immer, wenn Ihr einen Stapel von 'Mal des Todespirschers' aufbraucht, wird die Abklingzeit von 'Schattenschritt' um 3 Sek. verringert." }
entries[457058] = { ["name"] = "Dunkelste Nacht", ["text"] = "Täuschung\nWenn Ihr den letzten Stapel von 'Mal des Todespirschers' auf Eurem Ziel verbraucht oder Euer Ziel stirbt, erhaltet Ihr 40 Energie und Euer nächster Einsatz von 'Ausweiden' mit maximalen Combopunkten trifft garantiert kritisch, verursacht 60% zusätzlichen Schaden und belegt das Ziel mit 3 Stapeln von 'Mal des Todespirschers'.\n\nMeucheln\nWenn Ihr den letzten Stapel von 'Mal des Todespirschers' auf Eurem Ziel verbraucht oder Euer Ziel stirbt, erhaltet Ihr 40 Energie und Euer nächster Einsatz von 'Vergiften' mit maximalen Combopunkten trifft garantiert kritisch, verursacht 60% zusätzlichen Schaden und belegt das Ziel mit 3 Stapeln von 'Mal des Todespirschers'." }
entries[457059] = { ["name"] = "Flame Rift [NYI]", ["text"] = "'Dimensionsriss' kann einen mächtigen 'Flammenriss' beschwören." }
entries[457060] = { ["name"] = "Lessons of Space-Time [NYI]", ["text"] = "Erhöht jeglichen verursachten Schaden um 0%, solange ein 'Dimensionsriss' offen ist." }
entries[457062] = { ["name"] = "Symbolischer Sieg", ["text"] = "Täuschung\n'Symbole des Todes' erhöht zusätzlich den Schaden Eures nächsten Einsatzes von 'Ausweiden' oder 'Schwarzpulver' um 18%.\n\nMeucheln\n'Tückische Klinge' erhöht zusätzlich den Schaden Eures nächsten Einsatzes von 'Vergiften' um 18%." }
entries[457063] = { ["name"] = "Schleier der Nacht", ["text"] = "Erhöht die Dauer von 'Verhüllender Nebel' um 5 Sek." }
entries[457064] = { ["name"] = "Instabile Risse", ["text"] = "Blitze aus dem 'Dimensionsriss' fügen Gegnern in der Nähe 25% des verursachten Schadens als Feuerschaden zu." }
entries[457065] = { ["name"] = "Habt Ihr gewonnen?", ["text"] = "10 Meter Reichweite\nSofort\nSchleudert einen flammenden Brocken, der Gegnern körperlichen Schaden sowie Strukturen in der Nähe 1000 Belagerungsschaden zufügt." }
entries[457066] = { ["name"] = "Verderbt das Blut", ["text"] = "'Blutung' verursacht immer, wenn es Schaden verursacht, zusätzlich (2.5% der Angriffskraft) Seuchenschaden. Bis zu 10-mal stapelbar. Erhöht die Dauer von 'Blutung' um 3 Sek." }
entries[457067] = { ["name"] = "Impuls der Verzweiflung", ["text"] = "Kritische Treffer mit ['Dolchfächer' / 'Shurikensturm'] erhöhen 12 Sek. lang die kritische Trefferchance von ['Dolchfächer' / 'Shurikensturm'] und ['Blutroter Sturm' / 'Schwarzpulver'] um 15% und deren kritischen Schaden um 32%." }
entries[457068] = { ["name"] = "Blutverfolgung", ["text"] = "['Dolchfächer' / 'Shurikensturm'] und ['Blutroter Sturm' / 'Schwarzpulver'] verursachen 30% mehr Schaden, während 2 oder mehr Gegner von 'Blutung' betroffen sind." }
