entries[457133] = { ["name"] = "Verderbt das Blut", ["text"] = "100 Meter Reichweite\nSofort\n'Blutung' verursacht immer, wenn es Schaden verursacht, zusätzlich (2.5% der Angriffskraft) Seuchenschaden. Bis zu 10-mal stapelbar. Erhöht die Dauer von 'Blutung' um 3 Sek." }
