entries[457136] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und erhaltet 1 Stunde lang 446 Ausdauer und 223 Beweglichkeit." }
entries[457138] = { ["name"] = "Makroraketenmassaker", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\nSehr wirksam bei unbeweglichen Zielen." }
entries[457140] = { ["name"] = "Schwarzmeerkanone", ["text"] = "Sofort" }
entries[457141] = { ["name"] = "Makroraketenmassaker", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt einen Beschuss aus Raketen, die alle Gegner innerhalb von 6 Metern um das Ziel mehrfach treffen und ihnen 4 Feuerschaden zufügen.\n\nSehr wirksam bei unbeweglichen Zielen." }
entries[457144] = { ["name"] = "Zum Schweigen gebrachter Sprecher", ["text"] = "200 Meter Reichweite\nSofort\nDieser Sprecher kämpft mit größerem Eifer weiter, nachdem er zusehen musste, wie einer der Seinen getötet wurde, und ruft die Lava um sich herum zu Hilfe. Der Sprecher pulsiert alle 3 Sek. 2909339 Feuerschaden auf alle Spielercharaktere. Zudem wird der Schaden dieses Sprechers um 25% erhöht." }
entries[457145] = { ["name"] = "Zorn des Aspekts", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nNutzt immense Hitze, um Felsbrocken präzise und mühelos zu beseitigen." }
entries[457146] = { ["name"] = "Düsterniseruption" }
entries[457148] = { ["name"] = "Schwarzmeerwelle", ["text"] = "99 Meter Reichweite\nWirken in 1 sek. 4 sek. Abklingzeit\nReagenzien:\nSchwarzmeerkanonenkugel\nFeuert Baron Revilgaz' Schwarzmeerkanone ab, fügt so Gegnern auf der Schwarzmeermarina mäßigen Schaden zu oder zerstört sofort einen Freudenreiter der Düsternisverschmolzenen." }
entries[457149] = { ["name"] = "Lethargischer Fluch", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nDer Zaubernde schlägt das Ziel mit einem dunkelheiterfüllten Dolch, verursacht Schattenschaden und verringert die Bewegungsgeschwindigkeit 12 Sek. lang um 30%." }
entries[457156] = { ["name"] = "Geschmiedete Siegesflagge", ["text"] = "Unbegrenzte Reichweite\nSofort\nPlatziert auf der Leiche eines gegnerischen Spielercharakters vor Euch eine Flagge." }
entries[457157] = { ["name"] = "Mal des Todespirschers", ["text"] = "30 Meter Reichweite\nSofort\nMeucheln\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Hinterhalt' aus der Verstohlenheit einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von 'Hinterhalt' oder 'Verstümmeln' um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein.\n\nTäuschung\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Schattenschlag' aus der Verstohlenheit oder 'Schattentanz' einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein." }
entries[457160] = { ["name"] = "Mal des Todespirschers", ["text"] = "Sofort\nMeucheln\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Hinterhalt' aus der Verstohlenheit einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von 'Hinterhalt' oder 'Verstümmeln' um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein.\n\nTäuschung\nBelegt Euer Ziel mit 3 Stapeln von 'Mal des Todespirschers', wenn Ihr 'Schattenschlag' aus der Verstohlenheit oder 'Schattentanz' einsetzt. Wenn Ihr 5 oder mehr Combopunkte für Angriffe gegen ein markiertes Ziel einsetzt, verbraucht Ihr ein 'Mal des Todespirschers' auf dem Ziel, was (120% der Angriffskraft) Seuchenschaden verursacht und den Schaden Eures nächsten Einsatzes von um 50% erhöht.\nEs kann immer nur ein Gegner zur gleichen Zeit mit einem Mal belegt sein." }
