entries[457178] = { ["name"] = "Beseitigt die Zeugen", ["text"] = "Sofort\nNachdem Ihr ein Ziel mit 'Mal des Todespirschers' belegt, verursacht Euer nächster Einsatz von [ Meucheln : 'Dolchfächer' /\n\nTäuschung\n'Shurikensturm' ] zusätzlich (100% der Angriffskraft) Seuchenschaden und erzeugt 1 zusätzlichen Combopunkt." }
